"""Jira transport — REST API for issue/sprint/board operations.

All operations go through the Jira Cloud REST API (via curl, see `_api_call`).
`acli` is probed only as a health-check availability signal (`check_cli`), not
used operationally. MCP support via Atlassian Rovo is deferred to runtime
detection.

Auth: JIRA_API_TOKEN + JIRA_USER_EMAIL env vars.
"""

import json
import os
import re
import subprocess
from typing import Optional

from ..base import AdapterError, AdapterAuthError, AdapterOfflineError


def _norm_status(s: str) -> str:
    """Normalize a status/transition name for matching: strip whitespace,
    underscores and hyphens, then casefold. So "In Review", "IN REVIEW",
    "in_review" and "In-Review" all compare equal."""
    return re.sub(r"[\s_\-]+", "", str(s)).casefold()


class JiraTransport:
    """Transport layer for Jira operations via the REST API (curl).

    All operations use direct REST API calls authenticated with
    JIRA_API_TOKEN + JIRA_USER_EMAIL. `acli` is only probed for a health-check
    availability signal (`check_cli`); it is not used operationally.
    """

    def __init__(self, url: str, project_key: str):
        """Initialize with Jira instance URL and project key.

        Args:
            url: Jira Cloud URL, e.g. 'https://yourteam.atlassian.net'
            project_key: Jira project key, e.g. 'ANC'
        """
        self.url = url.rstrip("/")
        self.project_key = project_key
        self._cli_available: Optional[bool] = None
        self._api_available: Optional[bool] = None

    def check_cli(self) -> bool:
        """Report whether the `acli` binary is installed (availability probe only).

        This is a health-check signal, not an operational gate — every Jira
        operation in this transport goes through the REST path (`_api_call`),
        authenticated via JIRA_API_TOKEN + JIRA_USER_EMAIL (see `check_api`).

        We probe with `acli --version`, which is stable across acli generations.
        The old bobswift `acli jira --action getServerInfo` syntax is rejected as
        an unknown flag by the current Atlassian `acli`, so it always reported the
        CLI unavailable — a misleading false-negative (see #102).
        """
        if self._cli_available is not None:
            return self._cli_available
        try:
            result = subprocess.run(
                ["acli", "--version"],
                capture_output=True, text=True, timeout=15,
            )
            self._cli_available = result.returncode == 0
        except (FileNotFoundError, subprocess.TimeoutExpired):
            self._cli_available = False
        return self._cli_available

    def check_api(self) -> bool:
        """Check if direct REST API access is configured via env vars."""
        if self._api_available is not None:
            return self._api_available
        token = os.environ.get("JIRA_API_TOKEN", "")
        email = os.environ.get("JIRA_USER_EMAIL", "")
        self._api_available = bool(token and email and self.url)
        return self._api_available

    def health_check(self) -> dict:
        cli = self.check_cli()
        api = self.check_api()
        return {
            "status": "ok" if (cli or api) else "offline",
            "mcp": False,
            "cli": cli,
            "api": api,
            "url": self.url,
            "project": self.project_key,
        }

    # ── Issues ───────────────────────────────────────────────

    def create_issue(self, issue_type: str, summary: str,
                     description: str = "",
                     parent_key: Optional[str] = None,
                     labels: Optional[list[str]] = None,
                     priority: Optional[str] = None,
                     sprint_id: Optional[int] = None,
                     story_points: Optional[int] = None,
                     fields: Optional[dict] = None) -> dict:
        """Create a Jira issue. Returns the issue JSON."""
        body: dict = {
            "fields": {
                "project": {"key": self.project_key},
                "issuetype": {"name": issue_type},
                "summary": summary,
            }
        }
        if description:
            body["fields"]["description"] = self._text_to_adf(description)
        if parent_key:
            body["fields"]["parent"] = {"key": parent_key}
        if labels:
            body["fields"]["labels"] = labels
        if priority:
            body["fields"]["priority"] = {"name": priority}
        if story_points is not None:
            body["fields"]["story_point_estimate"] = story_points
        if fields:
            body["fields"].update(fields)

        result = self._api_call("POST", "/rest/api/3/issue", body=body)
        issue_key = result.get("key", "")

        # Assign to sprint if specified (separate API call)
        if sprint_id and issue_key:
            try:
                self._api_call(
                    "POST", f"/rest/agile/1.0/sprint/{sprint_id}/issue",
                    body={"issues": [issue_key]},
                )
            except AdapterError:
                pass  # Sprint assignment is best-effort

        return self.get_issue(issue_key) if issue_key else result

    def get_issue(self, key: str) -> dict:
        """Get a Jira issue by key."""
        return self._api_call(
            "GET",
            f"/rest/api/3/issue/{key}?fields=summary,status,priority,"
            f"labels,issuetype,parent,sprint,story_point_estimate,"
            f"description,comment",
        )

    def update_issue(self, key: str, **updates) -> dict:
        """Update issue fields."""
        body: dict = {"fields": {}}
        if "summary" in updates:
            body["fields"]["summary"] = updates["summary"]
        if "description" in updates:
            body["fields"]["description"] = self._text_to_adf(updates["description"])
        if "labels" in updates:
            body["fields"]["labels"] = updates["labels"]
        if "priority" in updates:
            body["fields"]["priority"] = {"name": updates["priority"]}
        if "story_points" in updates:
            body["fields"]["story_point_estimate"] = updates["story_points"]
        if "parent" in updates:
            if updates["parent"]:
                body["fields"]["parent"] = {"key": updates["parent"]}
            else:
                body["fields"]["parent"] = None
        if body["fields"]:
            self._api_call("PUT", f"/rest/api/3/issue/{key}", body=body)
        return self.get_issue(key)

    def transition_issue(self, key: str, target_status: str) -> dict:
        """Transition an issue to a target status."""
        # Get available transitions
        transitions = self._api_call("GET", f"/rest/api/3/issue/{key}/transitions")
        # Match case- and separator-insensitively against the transition's
        # destination status name (`to.name`), falling back to the transition
        # action name. So a target "In Review" resolves an available
        # "IN REVIEW" / "in_review" / "In-Review" automatically.
        norm_target = _norm_status(target_status)
        for t in transitions.get("transitions", []):
            to_name = (t.get("to") or {}).get("name") or t.get("name", "")
            if _norm_status(to_name) == norm_target:
                self._api_call(
                    "POST", f"/rest/api/3/issue/{key}/transitions",
                    body={"transition": {"id": t["id"]}},
                )
                return self.get_issue(key)
        raise AdapterError(
            f"Cannot transition {key} to '{target_status}'. "
            f"Available: {[t.get('name') for t in transitions.get('transitions', [])]}"
        )

    def search_issues(self, jql: str, max_results: int = 200) -> list[dict]:
        """Search issues via JQL with automatic cursor-based pagination.

        Uses the /rest/api/3/search/jql endpoint (the legacy /rest/api/3/search
        endpoint was removed by Atlassian — see CHANGE-2046).
        Pagination uses nextPageToken instead of startAt.
        """
        all_issues: list[dict] = []
        page_size = min(max_results, 100)
        next_page_token: Optional[str] = None

        while True:
            body: dict = {
                "jql": jql,
                "maxResults": page_size,
                "fields": [
                    "summary", "status", "priority", "labels",
                    "issuetype", "parent", "sprint", "assignee",
                    "story_point_estimate", "description",
                ],
            }
            if next_page_token is not None:
                body["nextPageToken"] = next_page_token

            result = self._api_call("POST", "/rest/api/3/search/jql", body=body)
            issues = result.get("issues", [])
            all_issues.extend(issues)

            if result.get("isLast", True) or len(all_issues) >= max_results:
                break
            next_page_token = result.get("nextPageToken")
            if not next_page_token:
                break

        return all_issues[:max_results]

    def add_label(self, key: str, label: str) -> dict:
        """Add a label to an issue."""
        return self._api_call(
            "PUT", f"/rest/api/3/issue/{key}",
            body={"update": {"labels": [{"add": label}]}},
        )

    def remove_label(self, key: str, label: str) -> dict:
        """Remove a label from an issue."""
        return self._api_call(
            "PUT", f"/rest/api/3/issue/{key}",
            body={"update": {"labels": [{"remove": label}]}},
        )

    def delete_issue(self, key: str) -> None:
        """Delete an issue."""
        self._api_call("DELETE", f"/rest/api/3/issue/{key}")

    # ── Sprints ──────────────────────────────────────────────

    def get_board_id(self, project_key: str) -> Optional[int]:
        """Find the Scrum board for a project."""
        result = self._api_call(
            "GET",
            f"/rest/agile/1.0/board?projectKeyOrId={project_key}&type=scrum",
        )
        boards = result.get("values", [])
        if boards:
            return boards[0]["id"]
        return None

    def create_sprint(self, board_id: int, name: str,
                      goal: str = "",
                      start_date: Optional[str] = None,
                      end_date: Optional[str] = None) -> dict:
        """Create a sprint on a board."""
        body: dict = {"name": name, "originBoardId": board_id}
        if goal:
            body["goal"] = goal
        if start_date:
            body["startDate"] = start_date
        if end_date:
            body["endDate"] = end_date
        return self._api_call("POST", "/rest/agile/1.0/sprint", body=body)

    def list_sprints(self, board_id: int, state: str = "active,closed,future") -> list[dict]:
        """List sprints on a board."""
        result = self._api_call(
            "GET",
            f"/rest/agile/1.0/board/{board_id}/sprint?state={state}&maxResults=100",
        )
        return result.get("values", [])

    def get_sprint(self, sprint_id: int) -> dict:
        return self._api_call("GET", f"/rest/agile/1.0/sprint/{sprint_id}")

    def update_sprint(self, sprint_id: int, **fields) -> dict:
        body = {}
        if "state" in fields:
            body["state"] = fields["state"]
        if "name" in fields:
            body["name"] = fields["name"]
        if "goal" in fields:
            body["goal"] = fields["goal"]
        return self._api_call("PUT", f"/rest/agile/1.0/sprint/{sprint_id}", body=body)

    def start_sprint(self, sprint_id: int) -> dict:
        return self.update_sprint(sprint_id, state="active")

    def close_sprint(self, sprint_id: int) -> dict:
        return self.update_sprint(sprint_id, state="closed")

    def get_sprint_issues(self, sprint_id: int, max_results: int = 200) -> list[dict]:
        """Get all issues in a sprint."""
        result = self._api_call(
            "GET",
            f"/rest/agile/1.0/sprint/{sprint_id}/issue?maxResults={max_results}"
            f"&fields=summary,status,priority,labels,issuetype,parent,"
            f"sprint,story_point_estimate,description",
        )
        return result.get("issues", [])

    def move_issues_to_sprint(self, sprint_id: int, issue_keys: list[str]) -> None:
        """Move issues to a sprint."""
        self._api_call(
            "POST", f"/rest/agile/1.0/sprint/{sprint_id}/issue",
            body={"issues": issue_keys},
        )

    # ── Internal ─────────────────────────────────────────────

    def _api_call(self, method: str, path: str,
                  body: Optional[dict] = None) -> dict:
        """Call the Jira REST API via curl with basic auth."""
        if not self.check_api():
            raise AdapterOfflineError(
                "Jira API not configured. Set these env vars:\n"
                "  JIRA_API_TOKEN — API token from https://id.atlassian.net/manage-profile/security/api-tokens\n"
                "  JIRA_USER_EMAIL — Email address associated with the token\n"
                "  .synaptory.yaml tracker.jira.url — Your Jira Cloud URL"
            )

        token = os.environ["JIRA_API_TOKEN"]
        email = os.environ["JIRA_USER_EMAIL"]
        url = f"{self.url}{path}"

        cmd = [
            "curl", "-s", "-X", method, url,
            "-H", "Content-Type: application/json",
            "-H", "Accept: application/json",
            "-u", f"{email}:{token}",
        ]
        input_data = None
        if body is not None:
            input_data = json.dumps(body)
            cmd.extend(["-d", "@-"])

        try:
            result = subprocess.run(
                cmd, capture_output=True, text=True,
                input=input_data, timeout=30,
            )
            if result.returncode != 0:
                raise AdapterError(f"Jira API call failed: {result.stderr.strip()}")

            if not result.stdout.strip():
                return {}

            data = json.loads(result.stdout)

            # Check for Jira error responses
            if isinstance(data, dict):
                if "errorMessages" in data:
                    raise AdapterError(f"Jira error: {data['errorMessages']}")
                if "errors" in data and data["errors"]:
                    raise AdapterError(f"Jira validation error: {data['errors']}")

            return data

        except subprocess.TimeoutExpired:
            raise AdapterOfflineError(f"Jira API timed out: {method} {path}")
        except json.JSONDecodeError:
            if method == "DELETE":
                return {}
            raise AdapterError(f"Invalid JSON response from Jira: {method} {path}")

    @staticmethod
    def _text_to_adf(text: str) -> dict:
        """Convert plain text/markdown to Atlassian Document Format (ADF).

        ADF is Jira Cloud's native rich text format. This produces a simple
        paragraph-based document. For complex formatting, use the ADF builder.
        """
        paragraphs = []
        for paragraph in text.split("\n\n"):
            lines = paragraph.strip()
            if not lines:
                continue
            # Detect headings
            if lines.startswith("## "):
                paragraphs.append({
                    "type": "heading",
                    "attrs": {"level": 2},
                    "content": [{"type": "text", "text": lines[3:]}],
                })
            elif lines.startswith("# "):
                paragraphs.append({
                    "type": "heading",
                    "attrs": {"level": 1},
                    "content": [{"type": "text", "text": lines[2:]}],
                })
            elif lines.startswith("- [ ] ") or lines.startswith("- [x] "):
                # Task list
                items = []
                for line in lines.splitlines():
                    line = line.strip()
                    if line.startswith("- [x] "):
                        items.append({"type": "taskItem", "attrs": {"state": "DONE"},
                                      "content": [{"type": "text", "text": line[6:]}]})
                    elif line.startswith("- [ ] "):
                        items.append({"type": "taskItem", "attrs": {"state": "TODO"},
                                      "content": [{"type": "text", "text": line[6:]}]})
                if items:
                    paragraphs.append({"type": "taskList", "content": items})
            elif lines.startswith("- "):
                # Bullet list
                items = []
                for line in lines.splitlines():
                    line = line.strip()
                    if line.startswith("- "):
                        items.append({
                            "type": "listItem",
                            "content": [{"type": "paragraph",
                                         "content": [{"type": "text", "text": line[2:]}]}],
                        })
                if items:
                    paragraphs.append({"type": "bulletList", "content": items})
            else:
                paragraphs.append({
                    "type": "paragraph",
                    "content": [{"type": "text", "text": lines}],
                })

        return {
            "version": 1,
            "type": "doc",
            "content": paragraphs or [
                {"type": "paragraph", "content": [{"type": "text", "text": text}]}
            ],
        }
